// A node in the organizational hierarchy.
public class EmployeeNode {
    private final String name;
    private EmployeeNode left;
    private EmployeeNode right;

    public EmployeeNode(String name) {
        this.name = name;
    }

    public String getName() { return name; }
    public EmployeeNode getLeft() { return left; }
    public EmployeeNode getRight() { return right; }
    public void setLeft(EmployeeNode left) { this.left = left; }
    public void setRight(EmployeeNode right) { this.right = right; }
}
