package com.bank.conflict;

import java.util.logging.Logger;

// Finds the lowest common manager of two employees.
public class OrgLcaService {

    private static final Logger log = Logger.getLogger(OrgLcaService.class.getName());

    public EmployeeNode lca(EmployeeNode node, EmployeeNode p, EmployeeNode q) {
        // Base: null, or we hit one of the targets.
        if (node == null || node == p || node == q) {
            return node;
        }
        // Search both subtrees.
        EmployeeNode left = lca(node.getLeft(), p, q);
        EmployeeNode right = lca(node.getRight(), p, q);

        // One target found on each side → current node is the LCA.
        if (left != null && right != null) {
            return node;
        }
        // Otherwise propagate whichever side found something.
        return (left != null) ? left : right;
    }

    public EmployeeNode findCommonManager(EmployeeNode root, EmployeeNode p, EmployeeNode q) {
        EmployeeNode ancestor = lca(root, p, q);
        if (ancestor != null) {
            log.info(() -> "Lowest common manager of " + p.getName()
                    + " and " + q.getName() + " is " + ancestor.getName());
        } else {
            log.warning("No common manager found");
        }
        return ancestor;
    }
}
