package com.bank.conflict;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LcaDemo {

    private static final Logger log = Logger.getLogger(LcaDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Conflict-of-Interest Common Manager");

        //              CEO
        //            /      \
        //       RegionHead   AuditHead
        //        /     \
        //   Rajesh    Priya
        EmployeeNode ceo = new EmployeeNode("CEO");
        EmployeeNode regionHead = new EmployeeNode("RegionHead");
        EmployeeNode auditHead = new EmployeeNode("AuditHead");
        EmployeeNode rajesh = new EmployeeNode("Rajesh");
        EmployeeNode priya = new EmployeeNode("Priya");
        ceo.setLeft(regionHead);
        ceo.setRight(auditHead);
        regionHead.setLeft(rajesh);
        regionHead.setRight(priya);

        OrgLcaService service = new OrgLcaService();
        service.findCommonManager(ceo, rajesh, priya);     // RegionHead
        service.findCommonManager(ceo, rajesh, auditHead); // CEO
    }
}
